import { z } from 'zod';

import { chatModeSchema, interestsSchema, langSchema, messageTextSchema } from '../schemas.ts';
import { NOTICE_CODES } from './events.ts';

// --- Shared building blocks ---------------------------------------------------------------

/** Session ids are UUIDs generated by the gateway. */
export const sessionIdSchema = z.uuid();

/** Random per-session id shown to other participants (never a visitor id). */
export const participantIdSchema = z.string().regex(/^[A-Za-z0-9_-]{8,32}$/);

export const MAX_SDP_BYTES = 16 * 1024;
export const MAX_ICE_CANDIDATE_LENGTH = 1024;

const emptyPayload = z.object({}).default({});

// --- Client → server payloads -------------------------------------------------------------

export const queueJoinSchema = z.object({
  mode: chatModeSchema,
  lang: langSchema,
  interests: interestsSchema.default([]),
});

export const queueLeaveSchema = emptyPayload;
export const pingSchema = emptyPayload;

export const sessionRefSchema = z.object({ sessionId: sessionIdSchema });
export const chatNextSchema = sessionRefSchema;
export const chatEndSchema = sessionRefSchema;

export const chatMessageSchema = z.object({
  sessionId: sessionIdSchema,
  text: messageTextSchema,
  /** Client-generated id echoed in acks so the sender can match optimistic messages. */
  clientMsgId: z.string().min(1).max(64),
});

export const chatTypingSchema = z.object({
  sessionId: sessionIdSchema,
  isTyping: z.boolean(),
});

/** `sdp` is the SDP text; the event name (offer/answer) carries the description type. */
export const rtcDescriptionSchema = z.object({
  sessionId: sessionIdSchema,
  to: participantIdSchema,
  sdp: z.string().min(1).max(MAX_SDP_BYTES),
});

/** Mirrors RTCIceCandidateInit; an empty `candidate` string signals end-of-candidates. */
export const iceCandidateSchema = z.object({
  candidate: z.string().max(MAX_ICE_CANDIDATE_LENGTH),
  sdpMid: z.string().max(64).nullable().optional(),
  sdpMLineIndex: z.number().int().min(0).max(255).nullable().optional(),
  usernameFragment: z.string().max(256).nullable().optional(),
});

export const rtcIceSchema = z.object({
  sessionId: sessionIdSchema,
  to: participantIdSchema,
  candidate: iceCandidateSchema,
});

export const CANDIDATE_TYPES = ['host', 'srflx', 'prflx', 'relay', 'unknown'] as const;
const candidateTypeSchema = z.enum(CANDIDATE_TYPES);
const metric = (max: number) => z.number().min(0).max(max).nullable();

export const rtcSummarySchema = z.object({
  sessionId: sessionIdSchema,
  peer: participantIdSchema,
  localCandidateType: candidateTypeSchema,
  remoteCandidateType: candidateTypeSchema,
  avgRttMs: metric(60_000),
  avgBitrateKbps: metric(100_000),
  timeToConnectedMs: metric(600_000),
  failed: z.boolean(),
});

export const moderationSignalSchema = z.object({
  sessionId: sessionIdSchema,
  about: z.union([participantIdSchema, z.literal('self')]),
  /** Classifier label, e.g. "nudity" (labels are defined in Part 8). */
  kind: z.string().regex(/^[a-z_]{1,32}$/),
  score: z.number().min(0).max(1),
});

// --- Server → client payloads -------------------------------------------------------------

export const queueWaitingSchema = z.object({ since: z.iso.datetime() });

export const peerRoleSchema = z.object({
  participantId: participantIdSchema,
  /** For this pair, the receiver creates the offer (impolite peer). */
  initiator: z.boolean(),
  /** Perfect-negotiation politeness for this pair, from the receiver's point of view. */
  polite: z.boolean(),
});

export const matchFoundSchema = z.object({
  sessionId: sessionIdSchema,
  mode: chatModeSchema,
  topology: z.literal('mesh'),
  maxParticipants: z.number().int().min(2).max(16),
  selfParticipantId: participantIdSchema,
  peers: z.array(peerRoleSchema),
  commonInterests: z.array(z.string()),
});

export const participantJoinedSchema = peerRoleSchema.extend({ sessionId: sessionIdSchema });

export const chatMessageOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  id: z.string().min(1),
  text: z.string(),
  at: z.iso.datetime(),
});

export const chatTypingOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  isTyping: z.boolean(),
});

export const rtcDescriptionOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  sdp: z.string(),
});

export const rtcIceOutSchema = z.object({
  sessionId: sessionIdSchema,
  from: participantIdSchema,
  candidate: iceCandidateSchema,
});

export const peerLeftSchema = z.object({
  sessionId: sessionIdSchema,
  participantId: participantIdSchema,
  reason: z.enum(['left', 'disconnected']),
  sessionEnded: z.boolean(),
});

export const systemNoticeSchema = z.object({
  code: z.enum(NOTICE_CODES),
  message: z.string(),
});

export const pongSchema = z.object({ serverTime: z.number().int() });

export const chatMessageAckSchema = z.object({ id: z.string().min(1), at: z.iso.datetime() });
